-- SM64Map: Super Mario 64's castle grounds, castle, Bob-omb Battlefield and Bowser's arena inside Storror Parkour Pro.
--   F2 grounds   F3 castle   F4 Bob-omb Battlefield   F5 Bowser's arena   (each loads the scene and puts you at its start)
--   F8 back to the file select   F6 reload current scene (or grounds)   F7 back to the scene's start   F9 remove everything   F10 material probe
-- Level data is generated by the exporter from the user's own SM64 ROM.
--
-- Dev channel: write Lua into  <mod>/dev/cmd.lua  (first line "-- id: N"); it runs in the game thread and its
-- output is appended to <mod>/dev/out.txt.  Globals available there: SM64 (game module), LIB (helpers).

local function plog(msg) print("[SM64Map] " .. tostring(msg) .. "\n") end

-- Lua's garbage collector in generational mode, collecting young garbage often in small bites (a minor collection
-- every 4% of growth). The mod makes ~15-20 MB of short-lived garbage a second (every look into the engine makes
-- objects); left incremental, each cycle's atomic step stalled the game 40-106 ms every ~5 s ("its still stuttering",
-- 2026-10-17: measured 9 frames over 25 ms in 21 s; after, 1 over 25 ms in 26 s, worst 27 ms).
-- (and its whole-heap pass - a major collection, 25-30 ms over the 34 MB - only once the heap is five times what it was,
-- 400: done at 100 it came every few seconds of play and stalled it each time - "lots of lag", 2026-11-05. One is made
-- as each scene is ready instead, behind its transition: game.lua)
pcall(collectgarbage, "generational", 4, 400)

local SCRIPT_DIR = (debug.getinfo(1, "S").source:match("^@(.*[/\\])") or "")
local MOD_DIR = (SCRIPT_DIR:gsub("Scripts[/\\]$", ""))
local DEV_DIR = MOD_DIR .. "dev\\"

-- ---------------------------------------------------------------- dev command channel (registered first)
local last_id = nil
do  -- never re-run a command left over from before this start-up
    local f0 = io.open(DEV_DIR .. "cmd.lua", "r")
    if f0 then
        local s0 = f0:read("a"); f0:close()
        last_id = s0:match("^%-%-%s*id:%s*(%S+)")
    end
end
local function dev_out(text)
    local f = io.open(DEV_DIR .. "out.txt", "a")
    if f then f:write(text, "\n"); f:close() end
end

-- Everything this mod does runs on the game thread, from the one per-frame loop at the bottom of this
-- file. It used to be driven by LoopAsync timers, which run Lua on a second thread while the game thread
-- is also running it; the two met after level loads and the mod loader went down.
local function dev_poll()
    local f = io.open(DEV_DIR .. "cmd.lua", "r")
    if not f then return end
    local src = f:read("a")
    f:close()
    local id = src:match("^%-%-%s*id:%s*(%S+)")
    if not id or id == last_id then return end
    last_id = id
    dev_out("== run " .. id)
    local fn, err = load(src, "cmd", "t", _ENV)
    if not fn then dev_out("compile error: " .. tostring(err)); return end
    local ok, res = xpcall(fn, debug.traceback)
    dev_out((ok and "ok: " or "error: ") .. tostring(res))
end
plog("dev channel active at " .. DEV_DIR)

-- ---------------------------------------------------------------- game modules
local okl, LIB = xpcall(require, debug.traceback, "lib")
if not okl then plog("lib failed to load: " .. tostring(LIB)); return end
local okg, SM64 = xpcall(require, debug.traceback, "game")
if not okg then plog("game failed to load: " .. tostring(SM64)); return end
_G.LIB, _G.SM64 = LIB, SM64
local okm, MENU = xpcall(require, debug.traceback, "menu")
if not okm then plog("menu failed to load: " .. tostring(MENU)); MENU = nil end
_G.MENU = MENU
local okh, HEALTH = xpcall(require, debug.traceback, "health")
if not okh then plog("health failed to load: " .. tostring(HEALTH)); HEALTH = nil end
_G.HEALTH = HEALTH
-- (stale actors from a previous hot reload are swept the next time a scene loads, so the player never falls)

local function safe(fn, label)
    return function()
        ExecuteInGameThread(function()
            local ok, e = xpcall(fn, debug.traceback)
            if not ok then plog((label or "error") .. ": " .. tostring(e)) end
        end)
    end
end

local function in_menu() return MENU ~= nil and MENU.state == "menu" end
local function go(name)
    return safe(function()
        if in_menu() then return end
        SM64.load_scene(name)
    end, "load " .. name)
end

RegisterKeyBind(Key.F2, go("grounds"))
RegisterKeyBind(Key.F3, go("castle"))
RegisterKeyBind(Key.F4, go("bob"))
RegisterKeyBind(Key.F5, go("bowser"))
RegisterKeyBind(Key.F6, safe(function() SM64.load_scene(SM64.name or "grounds") end, "reload"))
RegisterKeyBind(Key.F7, safe(function() SM64.teleport_spawn() end, "teleport"))
RegisterKeyBind(Key.F8, safe(function() if MENU then MENU.back_to_menu() end end, "menu"))
RegisterKeyBind(Key.F9, safe(function() SM64.destroy_scene(); plog("removed") end, "remove"))
RegisterKeyBind(Key.F10, safe(function() LIB.init_materials(LIB.world()) end, "materials"))

-- the one loop: every frame, on the game thread
local last_t, boot_t, dev_t = os.clock(), 0.0, 0.0
-- The map changed under the mod (STORROR reloading it from its menu, the boot's own trip to the empty map): every
-- script's hold on the gone map's objects dropped, untouched, before anything runs in the new one. A script's own check
-- - the world's address - is not enough: the new map can be put where the old one was. ("crash" twice, 2026-11-03: the
-- map reloaded with STORROR's menu up on CHARACTER, then a moment into the next game an object of the old map reached
-- for.) Only scripts whose forget touches nothing are here; game.lua drops its scene its own way.
local FORGET_ON_MAP = { "charhold", "charpick", "clothpick", "mariolook", "health", "pause", "msettings", "water96",
    "lamps", "rooms", "dialog", "starselect", "transition", "dust", "fog", "loops", "mariocap", "movtex", "chomp",
    "boxes", "sunsky", "swimpose", "waterclimb", "twirl", "camlakitu", "butterfly", "scenery", "mirror", "cork",
    "painting", "roundoff", "footik", "fp", "swim", "slide", "flight", "hang", "hoot", "poles", "caps", "burn", "envfx",
    "bobomb", "complete", "mp", "gore", "music", "sfx", "film", "bowser_fight", "chat" }
local map_addr = nil
local function map_watch()
    local a = nil
    pcall(function() local w = LIB.world(); a = w and w:GetAddress() end)
    if not a or a == map_addr then return end
    local was = map_addr
    map_addr = a
    if not was then return end
    local n = 0
    for _, name in ipairs(FORGET_ON_MAP) do
        local m = package.loaded[name]
        if type(m) == "table" and type(m.forget) == "function" and pcall(m.forget) then n = n + 1 end
    end
    plog(string.format("the map changed: %d scripts' hold on the old one dropped", n))
end
local function frame()
    local now = os.clock()
    pcall(map_watch)
    local dt = math.min(now - last_t, 0.1)
    last_t = now
    local tr = _G.SM64_TRACE_UNTIL and now < _G.SM64_TRACE_UNTIL
    if tr then plog("trace frame: game") end
    local ok, e = pcall(SM64.tick)
    if not ok then plog("tick error: " .. tostring(e)) end
    if MENU then
        if tr then plog("trace frame: menu") end
        local ok2, e2 = pcall(MENU.tick, dt)
        if tr then plog("trace frame: menu done") end
        if not ok2 then plog("menu tick error: " .. tostring(e2)) end
        if HEALTH and MENU.state ~= "game" then pcall(HEALTH.hud_hide) end     -- no meter or counters over the title or the file select
        -- boot flow (~2 Hz): leave the city map for the empty map, then show the file select
        boot_t = boot_t + dt
        if boot_t >= 0.5 then
            boot_t = 0.0
            local ok3, e3 = pcall(MENU.boot_tick)
            if not ok3 then plog("boot error: " .. tostring(e3)) end
        end
    end
    dev_t = dev_t + dt
    if dev_t >= 0.5 then
        dev_t = 0.0
        pcall(dev_poll)
    end
end
LoopInGameThreadAfterFrames(1, function()
    -- (lib's lookups made once in the frame, and forgotten at its end whatever happens)
    if LIB.frame_begin then LIB.frame_begin() end
    local ok, e = pcall(frame)
    if LIB.frame_end then LIB.frame_end() end
    if not ok then plog("frame error: " .. tostring(e)) end
    return false
end)

plog("loaded (mod dir: " .. MOD_DIR .. ")")
